old="function displayCountsFromApi(payload){const raw=payload&&payload.display!==undefined?payload.display:[],out={};for(const e of (Array.isArray(raw)?raw:Object.values(raw||{}))){const id=String(e?(e.ID??e.id??''):'').trim(),q=Number(e?(e.quantity??e.amount??0):0);if(id&&q>0)out[id]=(out[id]||0)+q;}return out;}\nasync function reconcileDisplayCase(){if(!state.settings.displayTracking||!apiKey())return false;const payload=await apiFetch('user',{selections:'display'}),actual=displayCountsFromApi(payload),ids=new Set(activeLots().filter(l=>l&&(l.location===INV||l.location===DISP)).map(l=>String(l.itemId))),now=new Date().toISOString();let changed=false;for(const id of ids){const physical=Math.max(0,Number(actual[id]||0)),tracked=Math.max(0,balance(id,P,DISP)+balance(id,F,DISP)),delta=physical-tracked;if(delta>0){const available=Math.max(0,balance(id,P,INV)+balance(id,F,INV)),q=Math.min(delta,available);if(q>0){const m=localMove(id,q,INV,DISP);m.timestamp=now;m.apiVerified=true;m.verificationSource='DISPLAY_SNAPSHOT';m.notes='Display Case location reconciled from Torn API snapshot. Ownership and cost basis preserved; faction-owned stock allocated first.';changed=true;}if(delta>available)console.warn('[FLIQ] Display Case contains untracked quantity',id,delta-available);}else if(delta<0){const q=Math.min(-delta,tracked);if(q>0){const m=localMove(id,q,DISP,INV);m.timestamp=now;m.apiVerified=true;m.verificationSource='DISPLAY_SNAPSHOT';m.notes='Display Case location reconciled from Torn API snapshot. Ownership and cost basis preserved; faction-owned stock allocated first.';changed=true;}}}return changed;}"
new="""function displayCountsFromApi(payload){const raw=payload&&payload.display!==undefined?payload.display:[],out={};for(const e of (Array.isArray(raw)?raw:Object.values(raw||{}))){const id=String(e?(e.ID??e.id??''):'').trim(),q=Number(e?(e.quantity??e.amount??0):0);if(id&&q>0)out[id]=(out[id]||0)+q;}return out;}\nfunction displaySnapshotState(){if(!state.displaySnapshot||typeof state.displaySnapshot!=='object')state.displaySnapshot={counts:{},initializedAt:'',updatedAt:''};if(!state.displaySnapshot.counts||typeof state.displaySnapshot.counts!=='object')state.displaySnapshot.counts={};return state.displaySnapshot;}\nfunction migrateLegacyDisplaySnapshot(){const rows=state.movements.filter(m=>m&&m.status!=='VOID'&&m.verificationSource==='DISPLAY_SNAPSHOT'&&m.displayReconcileMode!=='DELTA'&&!m.receiptBatchId).slice().sort((a,b)=>new Date(b.timestamp||0)-new Date(a.timestamp||0));let changed=false;for(const m of rows){const dest=String(m.to||''),src=String(m.from||''),lots=state.lots.filter(l=>l&&l.status==='OPEN'&&String(l.sourceRef||'')===String(m.id)&&String(l.location||'')===dest&&Number(l.qtyRemaining||0)>0),qty=lots.reduce((n,l)=>n+Number(l.qtyRemaining||0),0);if(qty!==Number(m.qty||0))continue;for(const l of lots){const q=Number(l.qtyRemaining||0);l.qtyRemaining=0;l.status='VOID';l.voidedAt=new Date().toISOString();l.voidReason='Legacy Display snapshot correction';addLot({itemId:l.itemId,itemName:l.itemName,owner:l.owner,location:src,qty:q,sourceType:'DISPLAY_BASELINE_CORRECTION',sourceRef:m.id,rootId:l.rootId,costBasisKnown:l.costBasisKnown,costEach:l.costEach,mvAtSource:l.mvAtSource,notes:'Returned to prior LedgerIQ location because pre-existing Display Case stock was incorrectly treated as a new movement.'});}m.status='VOID';m.voidedAt=new Date().toISOString();m.voidReason='Legacy Display snapshot reconciliation treated pre-existing Display Case stock as a new movement';changed=true;}if(changed)state.displaySnapshot={counts:{},initializedAt:'',updatedAt:''};return changed;}\nasync function reconcileDisplayCase(){if(!state.settings.displayTracking||!apiKey())return false;const payload=await apiFetch('user',{selections:'display'}),actual=displayCountsFromApi(payload),snap=displaySnapshotState(),now=new Date().toISOString();if(!snap.initializedAt){snap.counts=actual;snap.initializedAt=now;snap.updatedAt=now;return false;}const prev=snap.counts||{},ids=new Set([...Object.keys(prev),...Object.keys(actual),...activeLots().filter(l=>l&&(l.location===INV||l.location===DISP)).map(l=>String(l.itemId))]);let changed=false;for(const id of ids){const physical=Math.max(0,Number(actual[id]||0)),before=Math.max(0,Number(prev[id]||0)),delta=physical-before;if(delta>0){const available=Math.max(0,balance(id,P,INV)+balance(id,F,INV)),q=Math.min(delta,available);if(q>0){const m=localMove(id,q,INV,DISP);m.timestamp=now;m.apiVerified=true;m.verificationSource='DISPLAY_SNAPSHOT';m.displayReconcileMode='DELTA';m.notes='Display Case change reconciled from Torn API delta. Ownership and cost basis preserved; faction-owned stock allocated first.';changed=true;}if(delta>available)console.warn('[FLIQ] Display Case increase exceeds tracked Personal Inventory',id,delta-available);}else if(delta<0){const tracked=Math.max(0,balance(id,P,DISP)+balance(id,F,DISP)),q=Math.min(-delta,tracked);if(q>0){const m=localMove(id,q,DISP,INV);m.timestamp=now;m.apiVerified=true;m.verificationSource='DISPLAY_SNAPSHOT';m.displayReconcileMode='DELTA';m.notes='Display Case change reconciled from Torn API delta. Ownership and cost basis preserved; faction-owned stock allocated first.';changed=true;}if((-delta)>tracked)console.warn('[FLIQ] Display Case decrease includes pre-existing untracked quantity',id,(-delta)-tracked);}}snap.counts=actual;snap.updatedAt=now;return changed;}"""
if old not in s: raise SystemExit('display reconcile block missing')
s=s.replace(old,new,1)

old="function inventoryRows(){const map=new Map();activeLots().forEach(l=>{if(!state.settings.displayTracking&&l.location===DISP)return;const k=String(l.itemId);if(!map.has(k))map.set(k,{itemId:k,itemName:l.itemName||itemName(k),personal:0,faction:0,personalDisplay:0,factionDisplay:0,mv:mv(k)});const r=map.get(k);if(l.location===INV&&l.owner===P)r.personal+=Number(l.qtyRemaining||0);if(l.location===INV&&l.owner===F)r.faction+=Number(l.qtyRemaining||0);if(l.location===DISP&&l.owner===P)r.personalDisplay+=Number(l.qtyRemaining||0);if(l.location===DISP&&l.owner===F)r.factionDisplay+=Number(l.qtyRemaining||0);});return Array.from(map.values()).sort((a,b)=>a.itemName.localeCompare(b.itemName));}"
new="function inventoryRows(){const map=new Map(),snap=displaySnapshotState(),physical=snap.counts||{};activeLots().forEach(l=>{if(!state.settings.displayTracking&&l.location===DISP)return;const k=String(l.itemId);if(!map.has(k))map.set(k,{itemId:k,itemName:l.itemName||itemName(k),personal:0,faction:0,personalDisplay:0,factionDisplay:0,physicalDisplay:Number(physical[k]||0),mv:mv(k)});const r=map.get(k);if(l.location===INV&&l.owner===P)r.personal+=Number(l.qtyRemaining||0);if(l.location===INV&&l.owner===F)r.faction+=Number(l.qtyRemaining||0);if(l.location===DISP&&l.owner===P)r.personalDisplay+=Number(l.qtyRemaining||0);if(l.location===DISP&&l.owner===F)r.factionDisplay+=Number(l.qtyRemaining||0);});if(state.settings.displayTracking)Object.keys(physical).forEach(k=>{if(!map.has(k))map.set(k,{itemId:k,itemName:itemName(k),personal:0,faction:0,personalDisplay:0,factionDisplay:0,physicalDisplay:Number(physical[k]||0),mv:mv(k)});});return Array.from(map.values()).map(r=>({...r,untrackedDisplay:Math.max(0,Number(r.physicalDisplay||0)-Number(r.personalDisplay||0)-Number(r.factionDisplay||0))})).sort((a,b)=>a.itemName.localeCompare(b.itemName));}"
